$started=Get-Date;$timings=[ordered]@{};function Invoke-ProbeStage([string]$Name,[scriptblock]$Action){$clock=[Diagnostics.Stopwatch]::StartNew();[IO.File]::AppendAllText($progressPath,([ordered]@{at=(Get-Date).ToString('o');stage=($Name.ToUpperInvariant()+'_START')}|ConvertTo-Json -Compress)+[Environment]::NewLine,[Text.UTF8Encoding]::new($false));try{&$Action}finally{$clock.Stop();$script:timings[$Name]=[int]$clock.ElapsedMilliseconds;[IO.File]::AppendAllText($progressPath,([ordered]@{at=(Get-Date).ToString('o');stage=($Name.ToUpperInvariant()+'_END')}|ConvertTo-Json -Compress)+[Environment]::NewLine,[Text.UTF8Encoding]::new($false))}}
