  if(-not(Test-Path -LiteralPath $loadReceipt -PathType Leaf)-or([IO.File]::ReadAllText($loadReceipt,[Text.Encoding]::UTF8)-notmatch'LOAD_OK')){throw 'SEMANTIC_PROBE_V30_LOAD_RECEIPT'};$summaryPath=Join-Path $run 'generation_summary.tsv';$detailsPath=Join-Path $run 'generation_details.tsv';if(-not(Test-Path $summaryPath)-or-not(Test-Path $detailsPath)){throw 'SEMANTIC_PROBE_V30_GENERATION_REPORT_MISSING'}
  $summary=@(Import-Csv -LiteralPath $summaryPath -Delimiter "`t" -Encoding UTF8);$details=@(Import-Csv -LiteralPath $detailsPath -Delimiter "`t" -Encoding UTF8);if($summary.Count-ne1-or[int]$summary[0].TASK_COUNT-ne$expected-or[int]$summary[0].SUCCESS_COUNT-ne$expected-or$details.Count-ne$expected-or@($details|Where-Object{([string]$_.STATUS).ToUpperInvariant()-cne'PASS'}).Count){throw 'SEMANTIC_PROBE_V30_GENERATION_NOT_ALL_PASS'}
  $mapping=Join-Path $run 'typed_source_mapping.tsv';Invoke-ProbeStage 'generation_mapping'{$script:map=&$mappingBuilder -DetailsPath $detailsPath -OutputPath $mapping -ExpectedCount $expected};if([string]$map.status-cne'PASS'-or[int]$map.mapping_count-ne$expected-or[int]$map.unique_native_count-ne$expected-or[int]$map.provisional_semantic_rank1_count-ne$ExpectedProvisionalSemanticRank1Count){throw 'SEMANTIC_PROBE_V30_MAPPING'}
  $grips=Join-Path $run 'native_grips_after_generation.tsv';Invoke-ProbeStage 'native_grip_inventory'{$null=&$ownedAction -ProcessId $ProcessId -Action NET_NATIVE_GRIP_INVENTORY -OwnerStatePath $ownerPath -ReportPath $grips -SkipPluginLoad -TimeoutSeconds $TimeoutSeconds};$gripRows=@(Import-Csv -LiteralPath $grips -Delimiter "`t" -Encoding UTF8|Where-Object{([string]$_.RXCLASS).ToUpperInvariant()-ceq'TDBDIMENSION2'-and([string]$_.LAYER).ToUpperInvariant()-ceq'PUB_DIM'});$gripGroups=@($gripRows|Group-Object HANDLE);if($gripGroups.Count-ne$expected-or$gripRows.Count-ne($expected*5)-or@($gripGroups|Where-Object{$_.Count-ne5}).Count){throw 'SEMANTIC_PROBE_V30_EXACT_FIVE_GRIP_SET'}
  $geometry=Join-Path $run 'target_polyline_segments_selected.tsv';$geometryRows=@(Import-Csv -LiteralPath $geometry -Delimiter "`t" -Encoding UTF8);$arcCount=@($geometryRows|Where-Object{([string]$_.SEGMENT_TYPE).ToUpperInvariant()-ceq'ARC'}).Count;$lineCount=@($geometryRows|Where-Object{([string]$_.SEGMENT_TYPE).ToUpperInvariant()-ceq'LINE'}).Count;if($geometryRows.Count-ne$expected-or$arcCount+$lineCount-ne$expected){throw 'SEMANTIC_PROBE_V30_GEOMETRY'}
  $semanticInventory=Join-Path $run 'native_dimension_semantic_inventory.tsv';$semanticProgress=Join-Path $run 'semantic_inventory_progress.tsv';$semanticObserved=Join-Path $run 'semantic_inventory_observed_command.txt';$null=&$commandBuilder -BusinessCommandPath $semanticBusiness -ProgressPath $semanticProgress -OutputPath $semanticObserved;$semanticStarted=$true;Invoke-ProbeStage 'rendered_angle_inventory'{$script:semanticObservation=&$observed -DocumentName $DocumentName -CommandPath $semanticObserved -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $ownerPath -ProgressPath $semanticProgress -ObservationDirectory (Join-Path $run 'semantic_inventory_observation') -DocumentBindTimeoutSeconds 12 -StartAckTimeoutSeconds 25 -CommandCompletionTimeoutSeconds $TimeoutSeconds}
  if(-not(Test-Path $semanticLoadReceipt)-or([IO.File]::ReadAllText($semanticLoadReceipt,[Text.Encoding]::UTF8)-notmatch'LOAD_OK')-or-not(Test-Path $semanticInventory)){throw 'SEMANTIC_PROBE_V30_SEMANTIC_INVENTORY_MISSING'};$semanticAuditPath=Join-Path $run 'native_dimension_semantic_audit.tsv';$semanticSummaryPath=Join-Path $run 'native_dimension_semantic_summary.json';&$PythonPath $semanticAudit --geometry $geometry --mapping $mapping --text-inventory $semanticInventory --output-audit $semanticAuditPath --output-summary $semanticSummaryPath|Out-Null;if($LASTEXITCODE-ne0){throw 'SEMANTIC_PROBE_V30_SEMANTIC_AUDIT_TOOL'};$semantic=Get-Content -LiteralPath $semanticSummaryPath -Raw -Encoding UTF8|ConvertFrom-Json;if([string]$semantic.status-cne'PASS'-or[int]$semantic.pass_count-ne$expected-or[int]$semantic.arc_count-ne$arcCount-or[int]$semantic.line_count-ne$lineCount-or[int]$semantic.fail_count-ne0-or[int]$semantic.arc_degree_marker_count-ne$arcCount){throw 'SEMANTIC_PROBE_V30_RENDERED_ANGLE_FAIL'}
  $viewBusiness=Join-Path $run 'view_refresh_business_command.txt';$viewProgress=Join-Path $run 'view_refresh_progress.tsv';$viewObserved=Join-Path $run 'view_refresh_observed_command.txt';[IO.File]::WriteAllText($viewBusiness,"_.ZOOM`n_E`n_.REGEN`n",[Text.UTF8Encoding]::new($false));$null=&$commandBuilder -BusinessCommandPath $viewBusiness -ProgressPath $viewProgress -OutputPath $viewObserved;$viewStarted=$true;Invoke-ProbeStage 'view_refresh'{$script:viewObservation=&$observed -DocumentName $DocumentName -CommandPath $viewObserved -ProcessId $ProcessId -WindowHandle $WindowHandle -OwnerStatePath $ownerPath -ProgressPath $viewProgress -ObservationDirectory (Join-Path $run 'view_refresh_observation') -DocumentBindTimeoutSeconds 12 -StartAckTimeoutSeconds 25 -CommandCompletionTimeoutSeconds $TimeoutSeconds}
